495	// ---------- studio_l2_payments_enabled (S15) ----------
496	
497	/**
498	 * Capability gate: returns true only if the studio has an active Stripe Connect
499	 * account with `charges_enabled` capability. Used by S16+ in-studio charge code
500	 * paths to refuse charges before the studio's KYC is complete.
501	 *
502	 * Called from: feature-gate layer + UI banner suppression on /dashboard.
503	 *
504	 * `reason` is populated only when `enabled=false`. Possible values:
505	 *   - 'no_connected_account'      — studio has not started Connect onboarding
506	 *   - 'onboarding_pending'        — account exists but KYC incomplete
507	 *   - 'onboarding_restricted'     — Stripe restricted the account (KYC docs needed)
508	 *   - 'onboarding_rejected'       — Stripe permanently rejected
509	 *   - 'charges_disabled'          — Stripe revoked charges capability
510	 */
511	export interface StudioL2PaymentsEnabledArgs {
512	  studioId: string;
513	}
514	export type StudioL2PaymentsEnabledResult = {
515	  enabled: boolean;
516	  reason: string | null;
517	  account_id: string | null;
518	  onboarding_status: ConnectedAccountOnboardingStatus | null;
519	};
520	
521	// ---------- artist_l2_payouts_enabled (S15) ----------
522	
523	/**
524	 * Capability gate for artists who opt into direct payouts.
525	 * Returns true only if the artist has their own active Stripe Connect account
526	 * with `payouts_enabled` AND `transfers` capabilities.
527	 *
528	 * If false, commission splits flow to the studio's connected account and the
529	 * studio pays the artist via existing payroll path (1099 or W-2).
530	 *
531	 * `reason` possible values:
532	 *   - 'self_payouts_disabled'     — artist hasn't opted in (`payouts_self_enabled=false`)
533	 *   - 'no_connected_account'      — opted in but no Stripe account created yet
534	 *   - 'onboarding_pending'        — account exists, KYC incomplete
535	 *   - 'onboarding_restricted'     — Stripe restricted
536	 *   - 'onboarding_rejected'       — permanently rejected
537	 *   - 'transfers_disabled'        — capability missing
538	 *   - 'payouts_disabled'          — capability missing
539	 */
540	export interface ArtistL2PayoutsEnabledArgs {
541	  artistId: string;
542	}
543	export type ArtistL2PayoutsEnabledResult = {
544	  enabled: boolean;
545	  reason: string | null;
546	  account_id: string | null;
547	  onboarding_status: ConnectedAccountOnboardingStatus | null;
548	};
