96	-- SECTION 1 — TABLE: webhook_events
97	--
98	-- First write of every webhook handler (both Dodo L1 and Stripe L2).
99	-- UNIQUE (source, event_id) is the idempotency key.
100	-- No studio_id — events are platform-level; handlers resolve studio after insert.
101	-- RLS: service_role only. App code never reads/writes this table directly.
102	--
103	-- NOTE: webhook_events already exists in the Supabase cloud schema (minimal shape:
104	--   id, source, event_id, payload, processed_at, error, created_at).
105	-- This migration:
106	--   a) Creates the table if it doesn't exist (fresh DB / local reset).
107	--   b) ALTERs the table to add missing Sprint 13 columns (idempotent).
108	-- =============================================================================
109	
110	CREATE TABLE IF NOT EXISTS webhook_events (
111	  id                  uuid        NOT NULL DEFAULT gen_random_uuid(),
112	  source              text        NOT NULL,
113	  event_id            text        NOT NULL,
114	  event_type          text        NOT NULL DEFAULT '',
115	  payload             jsonb       NOT NULL DEFAULT '{}'::jsonb,
116	  signature_verified  boolean     NOT NULL DEFAULT false,
117	  processed_at        timestamptz NULL,
118	  error               text        NULL,
119	  retry_count         integer     NOT NULL DEFAULT 0,
120	  created_at          timestamptz NOT NULL DEFAULT now(),
121	
122	  CONSTRAINT webhook_events_pkey PRIMARY KEY (id),
123	  CONSTRAINT webhook_events_source_event_id_key UNIQUE (source, event_id)
124	);
125	
126	-- Extend existing table with Sprint 13 columns (ADD COLUMN IF NOT EXISTS is idempotent)
127	ALTER TABLE webhook_events
128	  ADD COLUMN IF NOT EXISTS event_type         text        NOT NULL DEFAULT '',
129	  ADD COLUMN IF NOT EXISTS signature_verified boolean     NOT NULL DEFAULT false,
130	  ADD COLUMN IF NOT EXISTS retry_count        integer     NOT NULL DEFAULT 0;
131	
132	-- Add source CHECK constraint if not already present (DO block is idempotent)
133	DO $$
134	BEGIN
135	  IF NOT EXISTS (
136	    SELECT 1 FROM information_schema.check_constraints
137	     WHERE constraint_name = 'webhook_events_source_check'
138	  ) THEN
139	    ALTER TABLE webhook_events
140	      ADD CONSTRAINT webhook_events_source_check
141	        CHECK (source IN ('dodo', 'stripe'));
142	  END IF;
143	END;
144	$$;
